const items = $input.all();

// Group articles by source feed
const grouped = {};
for (const item of items) {
  const source = item.json.feed?.title || 'Other';
  if (!grouped[source]) grouped[source] = [];
  grouped[source].push(item.json);
}

// Build HTML
let html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    body { font-family: Arial, sans-serif; max-width: 650px; 
           margin: 0 auto; background: #f5f5f5; padding: 20px; }
    .header { background: #1a1a2e; color: white; padding: 20px; 
              border-radius: 8px 8px 0 0; text-align: center; }
    .header h1 { margin: 0; font-size: 22px; }
    .header p { margin: 5px 0 0; opacity: 0.7; font-size: 13px; }
    .section { background: white; margin-top: 2px; padding: 16px 20px; }
    .section h2 { font-size: 14px; color: #666; text-transform: uppercase; 
                  letter-spacing: 1px; margin: 0 0 12px; 
                  border-bottom: 2px solid #1a1a2e; padding-bottom: 6px; }
    .article { margin-bottom: 14px; padding-bottom: 14px; 
               border-bottom: 1px solid #eee; }
    .article:last-child { border-bottom: none; margin-bottom: 0; }
    .article a { color: #1a1a2e; font-size: 15px; font-weight: bold; 
                 text-decoration: none; line-height: 1.4; }
    .article a:hover { text-decoration: underline; }
    .article .meta { font-size: 12px; color: #999; margin-top: 4px; }
    .article .snippet { font-size: 13px; color: #555; 
                        margin-top: 6px; line-height: 1.5; }
    .footer { background: #1a1a2e; color: white; padding: 14px; 
              border-radius: 0 0 8px 8px; text-align: center; 
              font-size: 12px; opacity: 0.8; }
  </style>
</head>
<body>
  <div class="header">
    <h1>🌅 Your Morning Tech Digest</h1>
    <p>${new Date().toLocaleDateString('en-US', { 
      weekday: 'long', year: 'numeric', 
      month: 'long', day: 'numeric' 
    })} • Kathmandu</p>
  </div>
`;

// Add each feed section
for (const [source, articles] of Object.entries(grouped)) {
  html += `
  <div class="section">
    <h2>${source}</h2>
  `;

  for (const article of articles) {
    const date = article.pubDate 
      ? new Date(article.pubDate).toLocaleTimeString('en-US', 
          { hour: '2-digit', minute: '2-digit' }) 
      : '';
    const snippet = article.contentSnippet 
      ? article.contentSnippet.substring(0, 120) + '...' 
      : '';

    html += `
    <div class="article">
      <a href="${article.link}" target="_blank">${article.title}</a>
      <div class="meta">Published at ${date}</div>
      ${snippet ? `<div class="snippet">${snippet}</div>` : ''}
    </div>
    `;
  }

  html += `</div>`;
}

const totalCount = items.length;

html += `
  <div class="footer">
    ${totalCount} articles curated for you today · Built with n8n
  </div>
</body>
</html>
`;

return [{ json: { html, totalCount, date: new Date().toISOString() } }];

const items = $input.all();
const cutoff = Date.now() - (24 * 60 * 60 * 1000);

// Keywords to keep (lowercase)
const keywords = [
  'automation', 'ai', 'n8n', 'workflow', 'nepal',
  'fintech', 'banking', 'claude', 'openai', 'llm'
];

// Step 1: filter by date AND keyword
let filtered = items.filter(item => {
  const data = item.json;

  // Date check
  if (!data.pubDate) return false;
  const d = new Date(data.pubDate);
  if (isNaN(d.getTime())) return false;
  if (d.getTime() <= cutoff) return false;

  // Keyword check — match in title or content
  const haystack = (
    (data.title || '') + ' ' + 
    (data.contentSnippet || '') + ' ' +
    (data.content || '')
  ).toLowerCase();

  return keywords.some(kw => haystack.includes(kw));
});

// Step 2: deduplicate by URL
const seen = new Set();
const unique = [];
for (const item of filtered) {
  const url = (item.json.link || '').trim().toLowerCase().replace(/\/$/, '');
  if (url && !seen.has(url)) {
    seen.add(url);
    unique.push(item);
  }
}

// Step 3: sort by date, newest first
unique.sort((a, b) => {
  const dateA = new Date(a.json.pubDate);
  const dateB = new Date(b.json.pubDate);
  return dateB - dateA;
});

// Step 4: limit to top 15
const limited = unique.slice(0, 15);

// Step 5: add parsed date for HTML template
return limited.map(item => ({
  json: {
    ...item.json,
    pubDateParsed: new Date(item.json.pubDate).toISOString()
  }
}));
